    39  // Test that zmq_connect can handle malformed strings
    40  extern "C" int LLVMFuzzerTestOneInput (const uint8_t *data, size_t size)
    41  {
    42      setup_test_context ();
    43      std::string my_endpoint (reinterpret_cast<const char *> (data), size);
    44      void *socket = test_context_socket (ZMQ_PUB);
    45      zmq_connect (socket, my_endpoint.c_str ());
    46
    47      test_context_socket_close_zero_linger (socket);
    48      teardown_test_context ();
    49
    50      return 0;
    51  }
    52
    53  #ifndef ZMQ_USE_FUZZING_ENGINE
    54  void test_connect_fuzzer ()
    55  {
    56      uint8_t buffer[32] = {0};
    57
    58      TEST_ASSERT_SUCCESS_ERRNO (
    59        LLVMFuzzerTestOneInput (buffer, sizeof (buffer)));
    60  }
    61
    62  int main (int argc, char **argv)
    63  {
    64      setup_test_environment ();
    65
    66      UNITY_BEGIN ();
    67      RUN_TEST (test_connect_fuzzer);
    68
    69      return UNITY_END ();
    70  }
    71  #endif
