   233  zmq::zmtp_engine_t::handshake_fun_t zmq::zmtp_engine_t::select_handshake_fun (
   234    bool unversioned_, unsigned char revision_, unsigned char minor_)
   235  {
   236      //  Is the peer using ZMTP/1.0 with no revision number?
   237      if (unversioned_) {
   238          return &zmtp_engine_t::handshake_v1_0_unversioned;
   239      }
   240      switch (revision_) {
   241          case ZMTP_1_0:
   242              return &zmtp_engine_t::handshake_v1_0;
   243          case ZMTP_2_0:
   244              return &zmtp_engine_t::handshake_v2_0;
   245          case ZMTP_3_x:
   246              switch (minor_) {
   247                  case 0:
   248                      return &zmtp_engine_t::handshake_v3_0;
   249                  default:
   250                      return &zmtp_engine_t::handshake_v3_1;
   251              }
   252          default:
   253              return &zmtp_engine_t::handshake_v3_1;
   254      }
   255  }
