   100  void zmq::zmtp_engine_t::plug_internal ()
   101  {
   102      // start optional timer, to prevent handshake hanging on no input
   103      set_handshake_timer ();
   104
   105      //  Send the 'length' and 'flags' fields of the routing id message.
   106      //  The 'length' field is encoded in the long format.
   107      _outpos = _greeting_send;
   108      _outpos[_outsize++] = UCHAR_MAX;
   109      put_uint64 (&_outpos[_outsize], _options.routing_id_size + 1);
   110      _outsize += 8;
   111      _outpos[_outsize++] = 0x7f;
   112
   113      set_pollin ();
   114      set_pollout ();
   115      //  Flush all the data that may have been already received downstream.
   116      in_event ();
