   123  bool zmq::zmtp_engine_t::handshake ()
   124  {
   125      zmq_assert (_greeting_bytes_read < _greeting_size);
   126      //  Receive the greeting.
   127      const int rc = receive_greeting ();
   128      if (rc == -1)
   129          return false;
   130      const bool unversioned = rc != 0;
   131
   132      if (!(this
   133              ->*select_handshake_fun (unversioned, _greeting_recv[revision_pos],
   134                                       _greeting_recv[minor_pos])) ())
   135          return false;
   136
   137      // Start polling for output if necessary.
   138      if (_outsize == 0)
   139          set_pollout ();
   140
   141      if (_has_handshake_timer) {
   142          cancel_timer (handshake_timer_id);
   143          _has_handshake_timer = false;
   144      }
   145
   146      return true;
   147  }
