   562  int zmq::zmtp_engine_t::process_command_message (msg_t *msg_)
   563  {
   564      const uint8_t cmd_name_size =
   565        *(static_cast<const uint8_t *> (msg_->data ()));
   566      const size_t ping_name_size = msg_t::ping_cmd_name_size - 1;
   567      const size_t sub_name_size = msg_t::sub_cmd_name_size - 1;
   568      const size_t cancel_name_size = msg_t::cancel_cmd_name_size - 1;
   569      //  Malformed command
   570      if (unlikely (msg_->size () < cmd_name_size + sizeof (cmd_name_size)))
   571          return -1;
   572
   573      const uint8_t *const cmd_name =
   574        static_cast<const uint8_t *> (msg_->data ()) + 1;
   575      if (cmd_name_size == ping_name_size
   576          && memcmp (cmd_name, "PING", cmd_name_size) == 0)
   577          msg_->set_flags (zmq::msg_t::ping);
   578      if (cmd_name_size == ping_name_size
   579          && memcmp (cmd_name, "PONG", cmd_name_size) == 0)
   580          msg_->set_flags (zmq::msg_t::pong);
   581      if (cmd_name_size == sub_name_size
   582          && memcmp (cmd_name, "SUBSCRIBE", cmd_name_size) == 0)
   583          msg_->set_flags (zmq::msg_t::subscribe);
   584      if (cmd_name_size == cancel_name_size
   585          && memcmp (cmd_name, "CANCEL", cmd_name_size) == 0)
   586          msg_->set_flags (zmq::msg_t::cancel);
   587
   588      if (msg_->is_ping () || msg_->is_pong ())
   589          return process_heartbeat_message (msg_);
   590
   591      return 0;
   592  }

